import{_ as a,a0 as i,w as l,s as d,I as p,x as n,a1 as o,A as s,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"人工智能教程（三）：更多有用的 Python 庫 | LCTT x X-CMD","titleTemplate":false,"description":"人工智能教程（三）：更多有用的 Python 庫 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"人工智能教程（三）：更多有用的 Python 庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"人工智能教程（三）：更多有用的 Python 庫 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20230727 AI- A Few More Useful Python Libraries","title":"人工智能教程（三）：更多有用的 Python 庫","tag":"202312","desc":""},"relativePath":"202312/20230727 AI- A Few More Useful Python Libraries.md","filePath":"[post].md"}'),u={name:"202312/20230727 AI- A Few More Useful Python Libraries.md"};function y(c,e,b,g,m,h){const t=i("Link");return l(),d("div",null,[e[35]||(e[35]=p("h1",{id:"人工智能教程-三-更多有用的-python-庫",tabindex:"-1"},[n("人工智能教程（三）：更多有用的 Python 庫 "),p("a",{class:"header-anchor",href:"#人工智能教程-三-更多有用的-python-庫","aria-label":"Permalink to “人工智能教程（三）：更多有用的 Python 庫”"},"​")],-1)),e[36]||(e[36]=p("p",null,[p("img",{src:"https://img.linux.net.cn/data/attachment/album/202312/02/214131dn96f43yff43w5fw.png",alt:""})],-1)),p("p",null,[e[1]||(e[1]=n("在本系列的 ",-1)),o(t,{href:"https://linux.cn/article-16399-1.html"},{default:s(()=>[...e[0]||(e[0]=[n("上一篇文章",-1)])]),_:1}),e[2]||(e[2]=n(" 中，我們回顧了人工智能的歷史，然後詳細地討論了矩陣。在本系列的第三篇文章中，我們將瞭解更多的矩陣操作，同時再介紹幾個人工智能 Python 庫。",-1))]),e[37]||(e[37]=r('<p>在進入主題之前，我們先討論幾個人工智能和機器學習中常用的重要術語。<ruby>人工神經網絡<rt>artificial neural network</rt></ruby>（通常簡稱為 <ruby>神經網絡<rt>neural network</rt></ruby>，NN）是機器學習和深度學習的核心。顧名思義，它是受人腦的生物神經網絡啓發而設計的計算模型。本文中我沒有插入神經網絡模型的圖片，因為在互聯網上很容易找到它們。我相信任何對人工智能感興趣的人應該都見過它們，左邊是輸入層，中間是一個或多個隱藏層，右邊是輸出層。各層之間的邊上的 <ruby>權重<rt>weight</rt></ruby> 會隨着訓練不斷變化。它是機器學習和深度學習應用成功的關鍵。</p><p><ruby>監督學習<rt>supervised learning</rt></ruby> 和 <ruby>無監督學習<rt>unsupervised learning</rt></ruby> 是兩個重要的機器學習模型。從長遠來看，任何立志於從事人工智能或機器學習領域工作的人都需要學習它們，並瞭解實現它們的各種技術。這裏我認為有必要簡單説明兩種模型之間的區別了。假設有兩個人分別叫 A 和 B，他們要把蘋果和橘子分成兩組。他們從未見過蘋果或橘子。他們都通過 100 張蘋果和橘子的圖片來學習這兩種水果的特徵（這個過程稱為模型的訓練）。不過 A 還有照片中哪些是蘋果哪些是橘子的額外信息（這個額外信息稱為標籤）。這裏 A 就像是一個監督學習模型，B 就像是無監督學習模型。你認為在是識別蘋果和橘子的任務上，誰的效果更好呢？大多數人可能會認為 A 的效果更好。但是根據機器學習的理論，情況並非總是如此。如果這 100 張照片中只有 5 張是蘋果，其它都是橘子呢？那麼 A 可能根本就不熟悉蘋果的特徵。或者如果部分標籤是錯誤的呢？在這些情況下，B 的表現可能比 A 更好。</p><p>在實際的機器學習應用中會發生這樣的情況嗎？是的！訓練模型用的數據集可能是不充分的或者不完整的。這是兩種模型都仍然在人工智能和機器學習領域蓬勃發展的眾多原因之一。在後續文章中，我們將更正式地討論它們。下面我們開始學習使用 JupyterLab，它是一個用於開發人工智能程序的強大工具。</p><h3 id="jupyterlab-入門" tabindex="-1">JupyterLab 入門 <a class="header-anchor" href="#jupyterlab-入門" aria-label="Permalink to “JupyterLab 入門”">​</a></h3><p>在本系列的前幾篇文章中，為了簡單起見，我們一直使用 Linux 終端運行 Python 代碼。現在要介紹另一個強大的人工智能工具——JupyterLab。在本系列的第一篇文章中，我們對比了幾個候選項，最終決定使用 JupyterLab。它比 Jupyter Notebook 功能更強大，為我們預裝了許多庫和包，並且易於團隊協作。還有一些其它原因，我們將在後續適時探討它們。</p>',5)),p("p",null,[e[4]||(e[4]=n("在本系列的第一篇文章中，我們已經學習瞭如何安裝 JupyterLab。假設你已經按文中的步驟安裝好了 JupyterLab，使用 ",-1)),e[5]||(e[5]=p("code",null,"jupyter lab",-1)),e[6]||(e[6]=n(" 或 ",-1)),e[7]||(e[7]=p("code",null,"jupyter-lab",-1)),e[8]||(e[8]=n(" 命令在會默認瀏覽器（如 Mozilla Firefox、谷歌 Chrome 等）中打開 JupyterLab。（LCTT 譯註：沒有安裝 JupyterLab 也不要緊，你可以先 ",-1)),o(t,{href:"https://jupyter.org/try-jupyter/lab/"},{default:s(()=>[...e[3]||(e[3]=[n("在線試用 JupyterLab",-1)])]),_:1}),e[9]||(e[9]=n("）圖 1 是在瀏覽器中打開的 JupyterLab 啓動器的局部截圖。JupyterLab 使用一個名為 IPython（交互式 Python）的 Python 控制台。注意，IPython 其實可以獨立使用，在 Linux 終端運行 ",-1)),e[10]||(e[10]=p("code",null,"ipython",-1)),e[11]||(e[11]=n(" 命令就可以啓動它。",-1))]),e[38]||(e[38]=p("p",null,[p("img",{src:"https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-1-The-launcher-of-the-JupyterLab-590x499.png",alt:"圖 1：JupyterLab 啓動器"})],-1)),p("p",null,[e[13]||(e[13]=n("現階段我們使用 JupyterLab 中的 Jupyter Notebook 功能。點擊圖 1 中用綠框標記的按鈕，打開 Jupyter Notebook。這時可能會要求你選擇內核。如果你按照本系列第一篇的步驟安裝 JupyterLab，那麼唯一的可選項就是 Python 3（ipykernel）。請注意，你還可以在 JupyterLab 中安裝其它編程語言的內核，比如 C++、R、MATLAB、Julia 等。事實上 Jupyter 的內核相當豐富，你可以訪問 ",-1)),o(t,{href:"https://github.com/jupyter/jupyter/wiki/Jupyter-kernels"},{default:s(()=>[...e[12]||(e[12]=[n("Jupyter 內核清單",-1)])]),_:1}),e[14]||(e[14]=n(" 瞭解更多信息。",-1))]),e[39]||(e[39]=r(`<p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-2-Jupyter-Notebook-window.png" alt="圖 2：Jupyter Notebook 窗口"></p><p>下面我們快速瞭解一下 Jupyter Notebook 的使用。圖 2 顯示的是一個在瀏覽器中打開的 Jupyter Notebook 窗口。從瀏覽器標籤頁的標題可以看出，Jupyter Notebook 打開的文件的擴展名是 <code>.ipynb</code>。</p><p>在圖 2 處可以看到有三個選項，它們表示 Jupyter Notebook 中可以使用的三種類型的單元。“Code”（綠色框） 表示代碼單元，它是用來執行代碼的。“Markdown” 單元可用於輸入説明性的文本。如果你是一名計算機培訓師，可以用代碼單元和 Markdown 單元來創建交互式代碼和解釋性文本，然後分享給你的學員。“Raw”（紅色框）表示原始數據單元，其中的內容不會被格式化或轉換。</p><p>和在終端中不同，在 Jupyter Notebook 中你可以編輯並重新運行代碼，這在處理簡單的拼寫錯誤時特別方便。圖 3 是在 Jupyter Notebook 中執行 Python 代碼的截圖。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-3-Python-code-executed-in-Jupyter-Notebook.png" alt="圖 3：在 Jupyter Notebook 中執行 Python 代碼"></p><p>要在執行代碼單元中的代碼，先選中該單元格，然後點擊藍框標記的按鈕。圖 3 中用紅框標記的是 Markdown 單元，用綠框標記的是代碼單元，用黃框標記的執行代碼的輸出。在這個例子中，Python 代碼輸出的是 π 的值。</p><p>前面提到，JupyterLab 默認安裝了許多庫和包，我們不用自己安裝了。你可以使用 <code>import</code> 命令將這些庫導入到代碼中。使用 <code>!pip freeze</code> 命令可以列出 JupyterLab 中目前可用的所有庫和包。如果有庫或包沒有安裝，大多數情況下都可以通過 <code>pip install &lt;全小寫的庫或者包的名稱&gt;</code> 來安裝它們。例如安裝 TensorFlow 的命令是 <code>pip install tensorflow</code>。如果後面有庫的安裝命令不遵循這個格式，我會進行特別説明。隨着本系列的繼續，我們還會看到 Jupyter Notebook 和 JupyterLab 更多強大的功能。</p><h3 id="複雜的矩陣運算" tabindex="-1">複雜的矩陣運算 <a class="header-anchor" href="#複雜的矩陣運算" aria-label="Permalink to “複雜的矩陣運算”">​</a></h3><p>通過下面的代碼，我們來了解一些更復雜的矩陣運算或操作。為了節省空間，我沒有展示代碼的輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import numpy as np</span></span>
<span class="line"><span>A = np.arr ay([[1,2,3],[4,5,6],[7,8,88]])</span></span>
<span class="line"><span>B = np.arr ay([[1,2,3],[4,5,6],[4,5,6]])</span></span>
<span class="line"><span>print(A.T)</span></span>
<span class="line"><span>print(A.T.T)</span></span>
<span class="line"><span>print(np.trace(A))</span></span>
<span class="line"><span>print(np.linalg.det(A))</span></span>
<span class="line"><span>C = np.linalg.inv(A)</span></span>
<span class="line"><span>print(C)</span></span>
<span class="line"><span>print(A@C)</span></span></code></pre></div><p>下面我逐行來解釋這些代碼：</p><ol><li>導入 NumPy 包。</li><li>創建矩陣 <code>A</code>。</li><li>創建矩陣 <code>B</code>。</li><li>打印矩陣 <code>A</code> 的<ruby>轉置<rt>transpose</rt></ruby>。通過比較矩陣 <code>A</code> 與 <code>A</code> 的轉置，你用該可以大致理解轉置操作到底做了什麼。</li><li>打印 <code>A</code> 的轉置的轉置。可以看到它和矩陣 <code>A</code> 是相同的。這又提示了轉置操作的含義。</li><li>打印矩陣 <code>A</code> 的 <ruby>跡<rt>trace</rt></ruby>。跡是矩陣的對角線（也稱為主對角線）元素的和。矩陣 <code>A</code> 的主對角線元素是 1、5 和 88，所以輸出的值是 94。</li><li>打印 <code>A</code> 的<ruby>行列式<rt>determinant</rt></ruby>。當執行代碼的結果是 -237.00000000000009（在你的電腦中可能略有區別）。因為行列式不為 0，所以稱 A 為<ruby>非奇異矩陣<rt>non-singular matrix</rt></ruby>。</li><li>將矩陣 <code>A</code> 的<ruby>逆<rt>inverse</rt></ruby> 保存到矩陣 <code>C</code> 中。</li><li>打印矩陣 <code>C</code>。</li><li>打印矩陣 <code>A</code> 和 <code>C</code> 的乘積。仔細觀察，你會看到乘積是一個<ruby>單位矩陣<rt>identity matrix</rt></ruby>，也就是一個所有對角線元素都為 1，所有其它元素都為 0 的矩陣。請注意，輸出中打印出的不是精確的 1 和 0。在我得到的答案中，有像 -3.81639165e-17 這樣的數字。這是浮點數的科學記數法，表示 -3.81639165 × 10<sup>-17</sup>， 即小數的 -0.0000000000000000381639165，它非常接近於零。同樣輸出中的其它數字也會有這種情況。我強烈建議你瞭解計算機是怎樣表示浮點數的，這對你會有很大幫助。</li></ol><p>根據第一篇文章中的慣例，可以將代碼分成基本 Python 代碼和人工智能代碼。在這個例子中，除了第 1 行和第 9 行之外的所有代碼行都可以被看作是人工智能代碼。</p><p>現在將第 4 行到第 10 行的操作應用到矩陣 B 上。從第 4 行到第 6 行代碼的輸出沒有什麼特別之處。然而運行第 7 行時，矩陣 <code>B</code> 的行列式為 0，因此它被稱為<ruby>奇異矩陣<rt>singular matrix</rt></ruby>。運行第 8 行代碼會給產生一個錯誤，因為只有非奇異矩陣才存在逆矩陣。你可以嘗試對本系列前一篇文章中的 8 個矩陣都應用相同的操作。通過觀察輸出，你會發現矩陣的行列式和求逆運算只適用於方陣。</p><p>方陣就是行數和列數相等的矩陣。在上面的例子中我只是展示了對矩陣執行各種操作，並沒有解釋它們背後的理論。如果你不知道或忘記了矩陣的轉置、逆、行列式等知識的話，你最好自己學習它們。同時你也應該瞭解一下不同類型的矩陣，比如單位矩陣、對角矩陣、三角矩陣、對稱矩陣、斜對稱矩陣。維基百科上的相關文章是不錯的入門。</p><p>現在讓我們來學習<ruby>矩陣分解<rt>matrix decomposition</rt></ruby>，它是更復雜的矩陣操作。矩陣分解與整數的因子分解類似，就是把一個矩陣被寫成其它矩陣的乘積。下面我通過圖 4 中整數分解的例子來解釋矩陣分解的必要性。代碼單元開頭的 <code>%time</code> 是 Jupyter Notebook 的<ruby>魔法命令<rt>magic command</rt></ruby>，它會打印代碼運行所花費的時間。<code>**</code> 是 Python 的冪運算符。基本的代數知識告訴我們，變量 a 和 b 的值都等於 (6869 x 7873)<sup>100</sup>。但圖 4 顯示計算變量 b 的速度要快得多。事實上，隨着底數和指數的增大，執行時間的減少會越來越明顯。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-4-Execution-time-of-a-Python-code-350x301.png" alt="圖 4：Python 代碼的執行耗時"></p><p>在幾乎所有的矩陣分解技術技術中，原始矩陣都會被寫成更稀疏的矩陣的乘積。<ruby>稀疏矩陣<rt>sparse matrix</rt></ruby>是指有很多元素值為零的矩陣。在分解後，我們可以處理稀疏矩陣，而不是原始的具有大量非零元素的<ruby>密集矩陣<rt>dense matrix</rt></ruby>。在本文中將介紹三種矩陣分解技術——LUP 分解、<ruby>特徵分解<rt>eigen decomposition</rt></ruby>和<ruby>奇異值分解<rt>singular value decomposition</rt></ruby>（SVD）。</p><p>為了執行矩陣分解，我們需要另一個強大的 Python 庫，SciPy。SciPy 是基於 NumPy 庫的科學計算庫，它提供了線性代數、積分、微分、優化等方面的函數。首先，讓我們討論 LUP 分解。任何方陣都能進行 LUP 分解。LUP 分解有一種變體，稱為 LU 分解。但並不是所有方陣都能 LU 分解。因此這裏我們只討論 LUP 分解。</p><p>在 LUP 分解中，矩陣 A 被寫成三個矩陣 L、U 和 P 的乘積。其中 L 是一個<ruby>下三角矩陣<rt>lower triangular matrix</rt></ruby>，它是主對角線以上的所有元素都為零的方陣。U 是一個<ruby>上三角矩陣<rt>upper triangular matrix</rt></ruby>，它是主對角線以下所有元素為零的方陣。P 是一個<ruby>排列矩陣<rt>permutation matrix</rt></ruby>。這是一個方陣，它的每一行和每一列中都有一個元素為 1，其它元素的值都是 0。</p><p>現在看下面的 LUP 分解的代碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import numpy as np</span></span>
<span class="line"><span>import scipy as sp</span></span>
<span class="line"><span>A=np.array([[11,22,33],[44,55,66],[77,88,888]])</span></span>
<span class="line"><span>P, L, U = sp.linalg.lu(A)</span></span>
<span class="line"><span>print(P)</span></span>
<span class="line"><span>print(L)</span></span>
<span class="line"><span>print(U)</span></span>
<span class="line"><span>print(P@L@U)</span></span></code></pre></div><p>圖 5 顯示了代碼的輸出。第 1 行和第 2 行導入 NumPy 和 SciPy 包。在第 3 行創建矩陣 <code>A</code>。請記住，我們在本節中會一直使用矩陣 <code>A</code>。第 4 行將矩陣 <code>A</code> 分解為三個矩陣——<code>P</code>、<code>L</code> 和 <code>U</code>。第 5 行到第 7 行打印矩陣 <code>P</code>、<code>L</code> 和 <code>U</code>。從圖 5 中可以清楚地看出，<code>P</code> 是一個置換矩陣，<code>L</code> 是一個下三角矩陣，<code>U</code> 是一個上三角矩陣。最後在第 8 行將這三個矩陣相乘並打印乘積矩陣。從圖 5 可以看到乘積矩陣 <code>P@L@U</code> 等於原始矩陣 <code>A</code>，滿足矩陣分解的性質。此外，圖 5 也驗證了矩陣 <code>L</code>、<code>U</code> 和 <code>P</code> 比矩陣 <code>A</code> 更稀疏。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-5-LUP-decomposition-with-SciPy-1-350x186.png" alt="圖 5：用 SciPy 進行 LUP 分解"></p><p>下面我們討論特徵分解，它是將一個方陣是用它的<ruby>特徵值<rt>eigenvalue</rt></ruby>和<ruby>特徵向量<rt>eigenvector</rt></ruby>來表示。用 Python 計算特徵值和特徵向量很容易。關於特徵值和特徵向量的理論解釋超出了本文的討論範圍，如果你不知道它們是什麼，我建議你通過維基百科等先了解它們，以便對正在執行的操作有一個清晰的概念。圖 6 中是特徵分解的代碼。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-6-Eigendecomposition-with-SciPy-350x175.png" alt="圖6：用 SciPy 進行特徵分解"></p><p>在圖 6 中，第 1 行計算特徵值和特徵向量。第 2 行和第 3 行輸出它們。注意，使用 NumPy 也能獲得類似的效果，<code>Lambda, Q = np.linalg.eig(A)</code>。這也告訴我們 NumPy 和 SciPy 的功能之間有一些重疊。第 4 行重建了原始矩陣 A。第 4 行中的代碼片段 <code>np.diag(Lambda)</code> 是將特徵值轉換為對角矩陣（記為 <code>Λ</code>）。對角矩陣是主對角線以外的所有元素都為 0 的矩陣。第 4 行的代碼片段 <code>sp.linalg.inv(Q)</code> 是求 <code>Q</code> 的逆矩陣（記為 Q<sup>-1</sup>）。最後，將三個矩陣 <code>Q</code>、<code>Λ</code>、<code>Q</code><sup>-1</sup> 相乘得到原始矩陣 <code>A</code>。也就是在特徵分解中 <code>A=QΛQ</code><sup>-1</sup>。</p><p>圖 6 還顯示了執行的代碼的輸出。紅框標記的是特徵值，用綠框標記的是特徵向量，重構的矩陣 A 用藍框標記。你可能會感到奇怪，輸出中像 11.+0.j 這樣的數字是什麼呢？其中的 j 是虛數單位。11.+0.j 其實就是 11.0+0.0j，即整數 11 的複數形式。</p><p>現在讓我們來看奇異值分解（SVD），它是特徵分解的推廣。圖 7 顯示了 SVD 的代碼和輸出。第 1 行將矩陣 <code>A</code> 分解為三個矩陣 <code>U</code>、<code>S</code> 和 <code>V</code>。第 2 行中的代碼片段 <code>np.diag(S)</code> 將 <code>S</code> 轉換為對角矩陣。最後，將這三個矩陣相乘重建原始矩陣 <code>A</code>。奇異值分解的優點是它可以對角化非方陣。但非方陣的奇異值分解的代碼稍微複雜一些，我們暫時不在這裏討論它。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-7-Singular-value-decomposition-with-SciPy-350x168.png" alt="圖 7：用 SciPy 進行 奇異值分解"></p><h3 id="其它人工智能和機器學習的-python-庫" tabindex="-1">其它人工智能和機器學習的 Python 庫 <a class="header-anchor" href="#其它人工智能和機器學習的-python-庫" aria-label="Permalink to “其它人工智能和機器學習的 Python 庫”">​</a></h3>`,31)),p("p",null,[e[16]||(e[16]=n("當談到人工智能時，普通人最先想到的場景可能就是電影《終結者》裏機器人通過視覺識別一個人。",-1)),e[17]||(e[17]=p("ruby",null,[n("計算機視覺"),p("rt",null,"computer vision")],-1)),e[18]||(e[18]=n("是人工智能和機器學習技術被應用得最廣泛的領域之一。下面我將介紹兩個計算機視覺相關的庫：OpenCV 和 Matplotlib。OpenCV 是一個主要用於實時計算機視覺的庫，它由 C 和 C++ 開發。C++ 是 OpenCV 的主要接口，它通過 OpenCV-Python 向用户提供 Python 接口。Matplotlib 是基於 Python 的繪圖庫。我曾在 OSFY 上的一篇早期 ",-1)),o(t,{href:"https://www.opensourceforu.com/2018/05/scientific-graphics-visualisation-an-introduction-to-matplotlib"},{default:s(()=>[...e[15]||(e[15]=[n("文章",-1)])]),_:1}),e[19]||(e[19]=n(" 中詳細介紹了 Matplotlib 的使用。",-1))]),e[40]||(e[40]=r(`<p>前面我一直在強調矩陣的重要性，現在我用一個實際的例子來加以説明。圖 8 展示了在 Jupyter Notebook 中使用 Matplotlib 讀取和顯示圖像的代碼和輸出。如果你沒有安裝 Matplotlib，使用 <code>pip install matplotlib</code> 命令安裝 Matplotlib。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-8-Reading-and-displaying-an-image-with-Matplotlib--350x278.png" alt="圖 8：用 Matplotlib 讀取和顯示圖像"></p><p>在圖 8 中，第 1 行和第 2 行從 Matplotlib 導入了一些函數。注意你可以從庫中導入單個函數或包，而不用導入整個庫。這兩行是基本的 Python 代碼。第 3 行從我的計算機中讀取標題為 <code>OSFY-Logo.jpg</code> 的圖像。我從 OSFY 門户網站的首頁下載了這張圖片。此圖像高 80 像素，寬 270 像素。第 4 行和第 5 行在 Jupyter Notebook 窗口中顯示圖像。請注意圖像下方用紅框標記的兩行代碼，它的輸出告訴我們變量 <code>image</code> 實際上是一個 NumPy 數組。具體來説，它是一個 80 x 270 x 3 的三維數組。</p><p>數組尺寸中的 80 x 270 就是圖片的大小，這一點很容易理解。但是第三維度表示什麼呢？這是因計算機像通常用 RGB 顏色模型來存儲的彩色圖。它有三層，分別用於表示紅綠藍三種原色。我相信你還記得學生時代的實驗，把原色混合成不同的顏色。例如，紅色和綠色混合在一起會得到黃色。在 RGB 模型中，每種顏色的亮度用 0 到 255 的數字表示。0 表示最暗，255 表示最亮。因此值為 <code>(255,255,255)</code> 的像素表示純白色。</p><p>現在，執行代碼 <code>print(image)</code>， Jupyter Notebook 會將整個數組的一部分部分打印出來。你可以看到數組的開頭有許多 255。這是什麼原因呢？如果你仔細看 OSFY 的圖標會發現，圖標的邊緣有很多白色區域，因此一開始就印了很多 255。順便説一句，你還可以瞭解一下其他顏色模型，如 CMY、CMYK、HSV 等。</p><p>現在我們反過來從一個數組創建一幅圖像。首先看圖 9 中所示的代碼。它展示瞭如何生成兩個 3 x 3 的隨機矩陣，它的元素是 0 到 255 之間的隨機值。注意，雖然相同的代碼執行了兩次，但生成的結果是不同的。這是通過調用 NumPy 的偽隨機數生成器函數 <code>randint</code> 實現的。實際上，我中彩票的幾率都比這兩個矩陣完全相等的幾率大得多。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-9-Two-matrices-with-random-entries-350x161.png" alt="圖 8：兩個隨機矩陣"></p><p>接下來我們要生成一個形狀為 512 x 512 x 3 的三維數組，然後將它轉換為圖像。為此我們將用到 OpenCV。注意，安裝 OpenCV 命令是 <code>pip install opencv-python</code>。看下面的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import cv2</span></span>
<span class="line"><span>img = np.random.randint(0, 256, size=(512, 512, 3))</span></span>
<span class="line"><span>cv2.imwrite(&#39;img.jpg&#39;, img)</span></span></code></pre></div><p>第 1 行導入庫 OpenCV。注意導入語句是 <code>import cv2</code>，這與大多數其他包的導入不同。第 3 行將矩陣 img 轉換為名為 <code>img.jpg</code> 的圖像。圖 10 顯示了由 OpenCV 生成的圖像。在系統中運行這段代碼，將圖像將被保存在 Jupyter Notebook 的同一目錄下。如果你查看這張圖片的屬性，你會看到它的高度是 512 像素，寬度是 512 像素。通過這些例子，很容易看出，任何處理計算機視覺任務的人工智能和機器學習程序使用了大量的數組、向量、矩陣以及線性代數中的思想。這也是本系列用大量篇幅介紹數組、向量和矩陣的原因。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/Figure-10-The-image-generated-by-OpenCV-350x366.png" alt="圖 10：OpenCV 生成的圖像"></p><p>最後，考慮下面顯示的代碼。<code>image.jpg</code> 輸出圖像會是什麼樣子？我給你兩個提示。函數 <code>zeros</code> 在第 4 行和第 5 行創建了兩個 512 x 512 的數組，其中綠色和藍色填充了零。第 7 行到第 9 行用來自數組 <code>red</code>、<code>green</code> 和 <code>blue</code> 的值填充三維數組 <code>img1</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import numpy as np</span></span>
<span class="line"><span>import cv2</span></span>
<span class="line"><span>red = np.random.randint(0, 256, size=(512, 512))</span></span>
<span class="line"><span>green = np.zeros([512, 512], dtype=np.uint8)</span></span>
<span class="line"><span>blue = np.zeros([512, 512], dtype=np.uint8)</span></span>
<span class="line"><span>img1 = np.zeros([512,512,3], dtype=np.uint8)</span></span>
<span class="line"><span>img1[:,:,0] = blue</span></span>
<span class="line"><span>img1[:,:,1] = green</span></span>
<span class="line"><span>img1[:,:,2] = red</span></span>
<span class="line"><span>cv2.imwrite(‘image.jpg’, img1)</span></span></code></pre></div><p>本期的內容就到此結束了。在下一篇文章中，我們將開始簡單地學習<ruby>張量<rt>tensor</rt></ruby>，然後安裝和使用 TensorFlow。TensorFlow 是人工智能和機器學習領域的重要參與者。之後，我們將暫時放下矩陣、向量和線性代數，開始學習概率論。概率論跟線性代數一樣是人工智能的重要基石。</p><p><em>（題圖：MJ/ec8e9a02-ae13-4924-b6cb-74ef96ab8af9）</em></p><hr>`,16)),p("p",null,[e[21]||(e[21]=n("via: ",-1)),o(t,{href:"https://www.opensourceforu.com/2023/07/ai-a-few-more-useful-python-libraries/"},{default:s(()=>[...e[20]||(e[20]=[n("https://www.opensourceforu.com/2023/07/ai-a-few-more-useful-python-libraries/",-1)])]),_:1})]),p("p",null,[e[26]||(e[26]=n("作者：",-1)),o(t,{href:"https://www.opensourceforu.com/author/deepu-benson/"},{default:s(()=>[...e[22]||(e[22]=[n("Deepu Benson",-1)])]),_:1}),e[27]||(e[27]=n(" 選題：",-1)),o(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[23]||(e[23]=[n("lujun9972",-1)])]),_:1}),e[28]||(e[28]=n(" 譯者：",-1)),o(t,{href:"https://github.com/toknow-gh"},{default:s(()=>[...e[24]||(e[24]=[n("toknow-gh",-1)])]),_:1}),e[29]||(e[29]=n(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[25]||(e[25]=[n("wxy",-1)])]),_:1})]),p("p",null,[e[32]||(e[32]=n("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[30]||(e[30]=[n("LCTT",-1)])]),_:1}),e[33]||(e[33]=n(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:s(()=>[...e[31]||(e[31]=[n("Linux中國",-1)])]),_:1}),e[34]||(e[34]=n(" 榮譽推出",-1))])])}const k=a(u,[["render",y]]);export{f as __pageData,k as default};
